with Signet;
procedure Multiply is
   V : constant Long_Float := Signet.Get_Float ("volts");
   I : constant Long_Float := Signet.Get_Float ("amps");
begin
   Signet.Put ("watts", V * I);
end Multiply;

// signet: in float::volts, in float::amps, out float::watts
use signet::{get_f64, put};
