    let watts = get_f64("volts") * get_f64("amps");
    put("watts", &watts, "");
}

// signet: in float::y, in float::r, in float::dt, in float::i
// signet: in float::yprev, in float::kp = 800.0
// signet: in float::ki = 80.0, in float::kd = 0.0
// signet: in float::umin = -3000.0, in float::umax = 4500.0
// signet: out float::u, out float::integral
#include <signet.hpp>
#include <algorithm>
int main() {
    auto in = [](auto n) { return signet::in<double>(n); };
    double y = in("y"), r = in("r"), dt = in("dt");
    double i = in("i"), yprev = in("yprev");
    double kp = in("kp"), ki = in("ki"), kd = in("kd");
    double lo = in("umin"), hi = in("umax");
    double e = r - y;
    double d = -kd * (y - yprev) / dt;       // On y, not e
    double u = kp * e + i + d;
    if (u > lo && u < hi) i += ki * e * dt;   // No windup
    signet::out("u", std::clamp(u, lo, hi));
    signet::out("integral", i);
}

